<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>$equipment['name'],'subtitle'=>$equipment['asset_code'].' · '.$equipment['category_name']]) ?><div class="detail-grid"><section class="panel"><div class="panel-head"><div><h2>Equipment Details</h2><p>Current inventory record</p></div><?php if($this->role()!=='borrower'&&$equipment['status']!=='retired'): ?><a class="btn" href="<?= site_url('equipment/'.$equipment['id'].'/edit') ?>">Edit</a><?php endif; ?></div><dl class="detail-list"><div><dt>Asset code</dt><dd><?= esc($equipment['asset_code']) ?></dd></div><div><dt>Category</dt><dd><?= esc($equipment['category_name']) ?></dd></div><div><dt>Location</dt><dd><?= esc($equipment['location_name']) ?></dd></div><div><dt>Total quantity</dt><dd><?= (int)$equipment['total_quantity'] ?> <?= esc($equipment['unit']) ?></dd></div><div><dt>Available now</dt><dd><strong><?= (int)$equipment['available_quantity'] ?></strong> <?= esc($equipment['unit']) ?></dd></div><div><dt>Condition</dt><dd><?= view('partials/status_badge',['status'=>$equipment['condition']]) ?></dd></div><div><dt>Status</dt><dd><?= view('partials/status_badge',['status'=>$equipment['status']]) ?></dd></div><div><dt>Acquired</dt><dd><?= esc(fmt_date($equipment['acquired_date'])) ?></dd></div></dl><?php if($equipment['description']): ?><div class="note-box"><b>Description</b><p><?= esc($equipment['description']) ?></p></div><?php endif; ?></section><?php if($this->role()==='borrower'): ?><aside class="panel action-panel"><h2>Borrow this equipment</h2><p>Submit a request with your purpose, dates, and desired quantity.</p><a class="btn primary wide" href="<?= site_url('borrow-requests/new') ?>">Create Borrowing Request</a></aside><?php else: ?><aside class="panel action-panel"><h2>Inventory Lifecycle</h2><?php if($equipment['status']==='retired'): ?><p>This record is retired and excluded from borrowing availability.</p><form method="post" action="<?= site_url('equipment/'.$equipment['id'].'/restore') ?>" data-confirm="Restore <?= esc($equipment['asset_code'].' · '.$equipment['name'],'attr') ?> as unavailable equipment? Review it before making it available again."><?= csrf_field() ?><button class="btn primary wide" type="submit">Restore Equipment</button></form><?php else: ?><p>Retiring removes this asset from active use without deleting its history. Pending or active borrowings and maintenance block retirement.</p><form method="post" action="<?= site_url('equipment/'.$equipment['id'].'/retire') ?>" data-confirm="Retire <?= esc($equipment['asset_code'].' · '.$equipment['name'],'attr') ?>? It will no longer be borrowable, and its history will be preserved."><?= csrf_field() ?><button class="btn danger wide" type="submit">Retire Equipment</button></form><?php endif; ?></aside><?php endif; ?></div><?= $this->endSection() ?>
